5	// DO NOT CHANGE THE SCHEMA NAME. IT IS 'member' AND SHOULD NOT BE MODIFIED.
6	// このスキーマ名は絶対に変更しないでください。'member' が正しい値です。
7	async function createSupabaseClient(isAdmin: boolean = false) {
8	  const cookieStore = await cookies()
9	
10	  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!
11	  const supabaseKey = isAdmin 
12	    ? process.env.SUPABASE_SERVICE_ROLE_KEY! 
13	    : process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
14	
15	  if (isAdmin && !process.env.SUPABASE_SERVICE_ROLE_KEY) {
16	    throw new Error('SUPABASE_SERVICE_ROLE_KEY is not defined in .env');
17	  }
18	
19	  return createServerClient(supabaseUrl, supabaseKey, {
20	    db: {
21	        schema: 'member', // DO NOT CHANGE THIS VALUE.
22	    },
23	    auth: {
24	      autoRefreshToken: !isAdmin,
25	      persistSession: !isAdmin,
26	      // Only the middleware should auto-refresh the session.
27	      // Other server-side clients should not.
28	      detectSessionInUrl: false,
29	    },
30	    cookies: {
31	      getAll() {
32	        return cookieStore.getAll()
33	      },
34	      setAll(cookiesToSet) {
35	        try {
36	          cookiesToSet.forEach(({ name, value, options }) =>
37	            cookieStore.set(name, value, options)
38	          )
39	        } catch {
40	          // The `setAll` method was called from a Server Component.
41	          // This can be ignored if you have middleware refreshing
42	          // user sessions.
43	        }
44	      },
45	    },
46	  })
47	}
48	
49	export async function createClient() {
50	  return await createSupabaseClient(false);
51	}
52	
53	export async function createAdminClient() {
54	  // service_roleクライアントはcookieベースのSSRクライアントを使わない。
